// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"bitcoin-halving":{"slug":"bitcoin-halving","cat":"basics","en":"Bitcoin halving","contentLocale":"zh-Hans","term":"比特币减半（Bitcoin Halving）","aka":["减半","Halving","BTC 减半"],"short":"比特币减半是指每产出 21 万个区块（约四年）矿工的区块奖励自动减少一半的规则，2024 年 4 月减半后奖励降至 3.125 BTC。","body":[[["比特币","bitcoin"],"没有央行决定发行量，新币全部来自区块奖励。协议规定每 210,000 个区块奖励减半一次，按约 10 分钟一个区块算，大约每四年一次。奖励从最初的每块 50 BTC 依次降到 25、12.5、6.25，2024 年 4 月降到 3.125 BTC。"],["减半让新增供应越来越少，最终使总量逼近 2100 万枚。对矿工来说，减半意味着同样的",["算力","hash-rate"],"收入直接减少一半（按币计），电费高、效率低的矿机可能被淘汰，全网算力和手续费收入的比重都会受到影响。"],"市场经常讨论减半前后的行情，但历史上的几次减半样本很少，宏观环境也各不相同。把减半当成“必涨信号”并不可靠，更合理的理解是：它改变的是新增供应速度，而价格取决于供需双方。"],"example":["按约 10 分钟一个区块计算，一天大约出 144 个区块。减半前每块 6.25 BTC，每天新增约 144 × 6.25 = 900 BTC；减半后每块 3.125 BTC，每天新增约 144 × 3.125 = 450 BTC。假设 BTC 价格为 60,000 ",["USDT","usdt"],"，全网矿工每天的区块奖励收入从约 5,400 万 USDT 降到约 2,700 万 USDT。"],"mistakes":["以为减半是比特币价格减半，实际上减半的是区块奖励。","认定减半后价格一定上涨，并据此重仓或加杠杆。","把减半时间当成固定日期，实际按区块高度触发，日期只是估算。"],"faq":[{"q":"比特币下一次减半是什么时候？","a":"下一次减半在第 1,050,000 个区块触发，按出块速度估算大约在 2028 年，具体日期会随出块速度略有浮动。"},{"q":"减半会影响我持有的比特币吗？","a":"不会。减半只影响新挖出的比特币数量，你钱包或账户里已有的 BTC 数量不变。"}],"title":"什么是比特币减半？减半的含义与影响","description":"比特币减半是什么意思、多久一次、2024 年减半后区块奖励变成多少，以及减半对矿工和新增供应的实际影响。","related":[["bitcoin","比特币（Bitcoin，BTC）","比特币是 2009 年上线的第一个去中心化加密货币，总量上限 2100 万枚，通过工作量证明挖矿维护网络，代号 BTC。"],["mining","挖矿（Crypto Mining）","挖矿是在工作量证明区块链上用计算设备竞争打包区块、维护网络安全并获得新币奖励和手续费的过程。"],["proof-of-work","工作量证明（PoW）","工作量证明（PoW）是一种共识机制，矿工通过大量计算竞争求解哈希难题，最先找到答案的人获得出块权和奖励，比特币采用这种机制。"],["hash-rate","算力（Hash rate）","算力是矿机或整个工作量证明网络每秒能完成的哈希计算次数，常用TH/s、EH/s表示，全网算力越高，攻击网络所需的成本通常越高。"],["satoshi","聪（Satoshi，sats）","聪是比特币的最小单位，1 BTC 等于 1 亿聪，以比特币创始人中本聪命名，英文常写作 sats。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"stop-loss":{"slug":"stop-loss","cat":"trading","en":"Stop-loss order","contentLocale":"zh-Hans","term":"止损单（Stop-Loss）","aka":["止损","Stop loss","SL"],"short":"止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。","body":[["止损单在触发前不会出现在",["订单簿","order-book"],"上，只是一个条件。价格达到触发价后，系统才会提交一笔",["市价单","market-order"],"或",["限价单","limit-order"],"。",["合约交易","futures-contract"],"里，止损通常可以直接挂在持仓上，触发后平掉仓位。"],["止损的意义在于让你在开仓前就决定最多愿意亏多少。在",["杠杆交易","margin-trading"],"中，合理的止损应该比",["强平价","liquidation-price"],"更早触发，否则就是让交易所替你“止损”，而爆仓损失的往往是整笔保证金。"],"止损也有局限：急跌时市价止损可能以比触发价差得多的价格成交；止损设得太近，正常波动就会把你扫出去。很多交易所允许选择用最新价还是标记价格触发，规则需要查看平台说明。"],"example":"假设你在 3.00 USDT 买入 1,000 枚某币，计划最多亏 150 USDT，于是止损设在 2.85 USDT。价格跌到 2.85 时触发市价卖出，因急跌实际均价为 2.83，你亏损约 170 USDT，比计划多了 20 USDT 的滑点。如果没设止损，价格一路跌到 2.20，你的浮亏就是 800 USDT。","mistakes":["开了杠杆却不设止损，指望价格回来，最后被强平。","价格接近止损时手动把止损往下挪，让小亏变大亏。","止损距离设得比日常波动还小，频繁被正常波动扫掉。"],"faq":[{"q":"止损单一定能按止损价成交吗？","a":"不一定。触发后若以市价执行，在急跌或流动性差时会有滑点；若用止损限价单，可能因价格跳过限价而不成交。"},{"q":"止损应该设在哪里？","a":"常见做法是设在交易逻辑失效的价位，比如跌破关键支撑，并结合该币的正常波动幅度，再据此计算仓位大小。"}],"title":"什么是止损单？止损的含义与设置方法","description":"止损单是什么？讲清止损如何触发和成交、为什么要比强平价更早止损、止损滑点的成因，以及如何确定止损位置和仓位。","related":[["take-profit","止盈单（Take-Profit）","止盈单是预先设定目标价，当价格朝有利方向达到该价位时自动卖出（或平仓）锁定利润的订单。"],["stop-limit-order","止损限价单（Stop-Limit Order）","止损限价单是包含触发价和限价两个价格的条件单，价格达到触发价后，系统以你设定的限价挂出一笔限价单。"],["trailing-stop","移动止损（Trailing Stop）","移动止损是一种会随价格朝有利方向移动而自动跟进的止损单，以固定比例或金额保持与最高价（或最低价）的距离，价格回撤到该距离时触发。"],["position-sizing","仓位管理（Position Sizing）","仓位管理是根据账户总资金、可承受的单笔亏损和止损距离，计算每笔交易应该开多大仓位的方法，目的是让任何一笔交易都不会重伤账户。"],["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"止盈止损，是计划，不是保险"},"coin":null,"tool":"/liquidations","cta":false},"unrealized-pnl":{"slug":"unrealized-pnl","cat":"derivatives","en":"Unrealized PnL","contentLocale":"zh-Hans","term":"未实现盈亏（Unrealized PnL）","aka":["浮动盈亏","浮盈浮亏","未实现收益","unrealized PnL"],"short":"未实现盈亏是仓位尚未平仓时，按当前价格（合约中通常是标记价格）计算出的账面盈利或亏损，只有平仓后才变成已实现盈亏。","body":[["币圈常说的“浮盈”“浮亏”就是未实现盈亏。多单的未实现盈亏 = (当前",["标记价格","mark-price"]," − 开仓均价) × 持仓数量；空单正好相反。价格每变一下，这个数字就跟着变。"],["在合约账户里，未实现盈亏直接影响保证金余额：浮亏会让保证金减少、",["强平价","liquidation-price"],"更近；在",["全仓模式","cross-margin"],"下，浮盈可以为其他仓位提供缓冲，部分",["交易所","centralized-exchange"],"还允许用浮盈开新仓，但规则各家不同。"],["未实现盈亏不等于你最终能拿到的钱。平仓时的实际",["成交价","last-price"],"可能和标记价格不同，还要扣除平仓手续费，持仓期间的",["资金费","funding-rate"],"也会单独结算到已实现盈亏中。"]],"example":"假设你在 60,000 USDT 开了 0.2 BTC 的多单。当前标记价格 62,500，未实现盈亏 = (62,500 − 60,000) × 0.2 = 500 USDT。如果你这时按 62,450 的市价平仓，并支付约 6 USDT 吃单手续费，实际落袋大约是 (62,450 − 60,000) × 0.2 − 6 = 484 USDT，比账面显示的 500 少一些。","mistakes":["把浮盈当成已经赚到的钱，在高位继续加仓。","以为浮亏不平仓就不算亏，忽略浮亏同样会把仓位推向强平。","忽略平仓手续费和资金费，对实际收益估计偏高。"],"faq":[{"q":"未实现盈亏和已实现盈亏有什么区别？","a":"未实现盈亏是还没平仓的账面盈亏，会随价格变化；已实现盈亏是平仓后确定下来的盈亏，通常还包含手续费和资金费。"},{"q":"浮亏会导致爆仓吗？","a":"会。合约中的浮亏会减少保证金余额，当余额低于维持保证金要求时就会触发强平。"}],"title":"未实现盈亏是什么？浮盈浮亏怎么计算","description":"解释合约中未实现盈亏（浮盈浮亏）的计算公式、它如何影响保证金和强平价，以及与平仓后的已实现盈亏有什么区别。","related":[["mark-price","标记价格（Mark Price）","标记价格是交易所用来计算未实现盈亏和判断强平的参考价格，通常以多家现货交易所的指数价格为基础，比最新成交价更难被短时操纵。"],["cross-margin","全仓保证金（Cross Margin）","全仓保证金是一种保证金模式，账户内所有可用余额共同为全部全仓仓位提供保证金，抗波动能力更强，但一旦强平可能亏掉整个账户余额。"],["liquidation-price","强平价（Liquidation Price）","强平价是标记价格达到后会触发仓位强制平仓的价格，由开仓价、杠杆倍数、维持保证金率以及保证金模式共同决定。"],["take-profit","止盈单（Take-Profit）","止盈单是预先设定目标价，当价格朝有利方向达到该价位时自动卖出（或平仓）锁定利润的订单。"]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"保证金为什么还没归零，就可能出局？"},"coin":null,"tool":null,"cta":false},"cold-wallet":{"slug":"cold-wallet","cat":"wallets-security","en":"Cold wallet (cold storage)","contentLocale":"zh-Hans","term":"冷钱包（冷存储）","aka":["冷存储","Cold wallet","Cold storage","离线钱包"],"short":"冷钱包是把私钥保存在不联网环境中的钱包或存储方式，例如硬件钱包和离线生成的纸钱包，主要用于长期、安全地存放大额加密资产。","body":[["冷钱包的核心是",["私钥","private-key"],"从不接触互联网。签名在离线设备内部完成，联网的电脑或手机只负责广播已经签好的交易，因此黑客即使控制了你的电脑，也拿不到私钥本身。"],["常见形式包括",["硬件钱包","hardware-wallet"],"、专门离线使用的旧手机，以及早期流行的纸钱包。",["交易所","centralized-exchange"],"也会把大部分用户资产放在冷钱包中，有的还配合多签，需要多人共同批准才能动用。"],["冷钱包不是绝对安全：备份的",["助记词","seed-phrase"],"被人看到、买到被动过手脚的设备、在签名时没核对地址，资产照样会丢。它的主要价值是防远程攻击，物理和人为风险仍要你自己管。"]],"example":["假设你打算",["长期持有","hodl"]," 0.8 ",["BTC","bitcoin"],"，每年只动一两次。你把它从交易所提到硬件钱包，在设备屏幕上核对收款地址前 6 位和后 6 位，再先转 0.001 BTC 测试。确认到账后再转剩余的 0.799 BTC。之后电脑即使中毒，攻击者也无法在没有设备和 PIN 码的情况下签名转走它。"],"mistakes":["以为把币放进冷钱包就万事大吉，却把助记词拍照存在手机里。","从二手平台购买已拆封的硬件钱包，或使用卖家预先写好的助记词。","大额首次转入时不做小额测试，地址或网络出错就整笔损失。"],"faq":[{"q":"冷钱包一定是硬件钱包吗？","a":"不一定。硬件钱包是最常见的冷钱包，但任何私钥离线生成、离线保存、离线签名的方式都算冷存储，比如专用离线设备。"},{"q":"冷钱包里的币能直接交易吗？","a":"不能直接在交易所买卖。你需要先签名把币转到交易所或连接 DEX，所以冷钱包更适合长期持有而非频繁交易。"}],"title":"什么是冷钱包？冷存储的含义与使用方法","description":"冷钱包是什么？了解冷存储如何离线保管私钥、与热钱包的区别、交易所为何用冷钱包，以及把资产转入冷钱包时的检查步骤。","related":[["hot-wallet","热钱包（Hot Wallet）","热钱包是私钥存放在联网设备上的加密货币钱包，例如手机钱包和浏览器插件钱包，使用方便，但更容易受到网络攻击。"],["hardware-wallet","硬件钱包（Hardware Wallet）","硬件钱包是一种专门保管私钥的小型实体设备，私钥在设备内部生成并签名，从不传到电脑或手机上，是最常用的冷钱包形式。"],["seed-phrase","助记词（Seed Phrase）","助记词是由 12 或 24 个英文单词组成的钱包备份，可以推导出钱包里的全部私钥，谁拿到助记词，谁就能控制这个钱包里的所有资产。"],["multisig-wallet","多签钱包（Multisig Wallet）","多签钱包是需要多把私钥中的若干把共同签名才能转出资产的钱包，例如“3 选 2”，常用于团队资金、DAO 金库和大额个人资产管理。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"币到底在哪：交易所和钱包有什么不同？"},"coin":null,"tool":null,"cta":false},"rug-pull":{"slug":"rug-pull","cat":"wallets-security","en":"Rug pull","contentLocale":"zh-Hans","term":"跑路（Rug Pull）","aka":["Rug pull","拉地毯","撤池子","项目跑路"],"short":"Rug Pull（跑路、拉地毯）是指项目方在吸引投资者买入后，突然撤走流动性池中的资金、大量抛售手中代币或卷走资金，导致代币价格瞬间归零。","body":[["最常见的方式是“撤池子”：项目方在 ",["DEX","dex"]," 上创建代币和一个配对的",["流动性池","liquidity-pool"],"，吸引大家用 ",["ETH","ethereum"],"、BNB 或 ",["USDT","usdt"]," 买入，随后一次性移除",["流动性","liquidity"],"，把池子里的真资产全部拿走，持有人手里的代币再也卖不出去。"],["其他形式包括：合约里预留了只能买不能卖的限制（貔貅盘）、增发后门、团队持有大量未锁仓代币后集中抛售，或者 ",["DeFi","defi"]," 项目直接卷走用户存款。新上线的土狗币和 Meme 币是重灾区。"],"可以检查的点：流动性是否锁仓、锁多久；合约是否开源并通过审计；持币是否高度集中；是否存在增发、黑名单、暂停交易等权限。这些检查只能降低风险，不能保证安全。"],"example":"假设某新代币上线时池子里有 50 ETH 和 1 亿枚代币。三天内大量散户买入，池子变成 300 ETH 和约 1,667 万枚代币。随后项目方移除全部流动性，带走 300 ETH，代币价格跌到几乎为零。你此前用 2 ETH 买入的代币，账面价值可能只剩不到 0.01 ETH，而且找不到买家。","mistakes":["只看涨幅和社群热度就冲进新币，不检查流动性是否锁仓。","以为合约审计过就一定不会跑路，忽略了团队仍持有大量代币。","买入后发现卖不出去，又追加资金想“摊低成本”。"],"faq":[{"q":"怎么判断一个代币会不会跑路？","a":"没有办法百分之百判断，但可以查看流动性锁仓情况、合约权限、持币分布和团队是否匿名，风险越多越要谨慎。"},{"q":"流动性锁仓了就安全了吗？","a":"不一定。锁仓只防撤池子，项目方仍可能通过抛售持仓、合约后门或到期解锁获利离场。"}],"title":"什么是 Rug Pull？币圈跑路的常见手法","description":"Rug Pull 跑路是什么意思？了解撤池子、貔貅盘、增发后门等常见手法，以及买入新币前应该检查的流动性锁仓和合约权限信号。","related":[["memecoin","Meme 币（Memecoin）","Meme 币是以网络梗、动物形象或社区文化为主题、通常没有明确实际用途的加密货币，价格主要由社区热度和投机驱动。"],["liquidity-pool","流动性池（Liquidity Pool）","流动性池是锁在智能合约里的一对或多种代币储备，交易者直接与池子兑换，存入资金的流动性提供者按份额获得手续费收入，是 DEX 运作的基础。"],["token-approval","代币授权（Token Approval）","代币授权是你在链上允许某个智能合约动用你钱包里指定代币的操作，授权额度决定合约最多能转走多少，常用于 DEX 交易和 DeFi 存款。"],["dex","去中心化交易所（DEX）","去中心化交易所（DEX）是基于智能合约运行的交易平台，你直接用自己的钱包交易，不需要注册账户或把资产托管给平台，典型代表有 Uniswap 和 PancakeSwap。"]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"别人说能帮你赚钱，先看他要什么"},"coin":null,"tool":"/topics/meme-coins","cta":false},"oracle":{"slug":"oracle","cat":"defi","en":"Blockchain oracle","contentLocale":"zh-Hans","term":"预言机（Oracle）","aka":["预言机","Oracle","价格预言机","喂价"],"short":"预言机是把链下数据（如币价、汇率、体育比分）传送到区块链上供智能合约使用的服务，DeFi 借贷、衍生品和稳定币都依赖它获取价格。","body":[[["智能合约","smart-contract"],"自己无法访问互联网，不知道 ",["ETH","ethereum"]," 现在值多少钱。预言机负责从多个",["交易所","centralized-exchange"],"和数据源收集价格，汇总后写到链上，合约再根据这个价格计算抵押率、触发清算或结算合约。Chainlink 是使用最广的去中心化预言机网络之一。"],["预言机的质量直接决定协议安全。如果价格只取自一个",["流动性","liquidity"],"很浅的 ",["DEX","dex"]," 池子，攻击者就可能用大额资金短时间操纵价格，让协议按错误价格放贷或清算，这类事件在 ",["DeFi","defi"]," 历史上反复出现。"],"好的预言机设计会聚合多个数据源、使用时间加权平均价、设置偏离阈值和更新频率。作为用户，了解你使用的协议采用哪种价格源，有助于判断清算是否可能被异常价格触发。"],"example":"假设某借贷协议直接用一个小池子的实时价格作为抵押品报价，池中有 10 万美元流动性。攻击者用闪电贷借来 200 万美元，在一笔交易内把该代币价格从 1 美元拉到 5 美元，以抬高后的价格抵押借出大量稳定币，再把价格砸回去。如果协议使用聚合多家交易所的预言机，这次单池操纵就很难生效。","mistakes":["以为链上价格永远准确，不了解协议使用的是哪种价格源。","在预言机更新较慢的协议上高杠杆操作，剧烈行情时被延迟价格清算。","把预言机和交易所的标记价格、指数价格混为一谈。"],"faq":[{"q":"为什么区块链需要预言机？","a":"区块链为了保证每个节点结果一致，不能直接读取外部数据，只能由预言机把经过验证的数据写到链上供合约读取。"},{"q":"预言机被攻击会怎样？","a":"错误的价格可能导致协议被低价清算、超额借款或资金被掏空。所以协议通常会聚合多源数据并设置保护机制。"}],"title":"什么是预言机？区块链 Oracle 的作用与风险","description":"预言机是什么意思？了解区块链 Oracle 如何把链下价格送上链、DeFi 借贷为何依赖它，以及价格操纵攻击是怎样发生的。","related":[["smart-contract","智能合约（Smart Contract）","智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。"],["defi-lending","DeFi 借贷","DeFi 借贷是通过智能合约进行的超额抵押借贷，存款人把资产存入资金池赚利息，借款人先存入抵押品再借出其他资产，抵押不足时会被自动清算。"],["index-price","指数价格（Index Price）","指数价格是交易所根据多家主流现货交易所的价格，按一定权重加权计算出的综合现货价格，用作标记价格和资金费率的基准。"],["flash-loan","闪电贷（Flash Loan）","闪电贷是一种无需抵押的链上借款，借款和还款必须在同一笔交易内完成，如果交易结束时没有连本带息还清，整笔交易就会被撤销，就像没发生过一样。"]],"lesson":null,"coin":{"slug":"chainlink","name":"Chainlink","symbol":"LINK"},"tool":null,"cta":false},"launchpad":{"slug":"launchpad","cat":"exchange-features","en":"Launchpad (token sale)","contentLocale":"zh-Hans","term":"Launchpad（新币首发认购）","aka":["Launchpad","打新","IEO","新币认购"],"short":"Launchpad是交易所或链上平台为新项目举办的代币首发认购活动，用户在上线交易前用稳定币或平台币按固定价格认购新币，超额认购时按比例分配。","body":[["Launchpad常被称为“打新”，",["中心化交易所","centralized-exchange"],"主办的也叫IEO。项目方以固定价格出售一部分代币，交易所负责审核和组织认购。参与资格通常与持有平台币的数量、",["KYC认证","kyc"],"和所在地区有关。"],"大多数活动采用承诺认购模式：你在承诺期内锁定资金，结束后系统按全部承诺金额计算你的分配比例。认购需求越大，每个人实际买到的份额越少，没用完的资金会退回。",["认购到的新币不等于稳赚。上线后价格可能高于认购价，也可能很快跌破；部分代币还设有解锁期，不能一次性全部卖出。参与前要看清",["代币经济模型","tokenomics"],"、解锁安排和总",["流通量","circulating-supply"],"，以及项目方和交易所公布的风险说明。"]],"example":["假设某项目通过Launchpad出售价值1,000,000 USDT的代币，认购价0.02 ",["USDT","usdt"],"。活动结束时总承诺金额达到20,000,000 USDT，超额认购20倍，每个人的分配比例为5%。你承诺了1,000 USDT，实际认购50 USDT，获得2,500枚代币，其余950 USDT退回。上线后若价格为0.03 USDT，这2,500枚值75 USDT，盈利25 USDT；若跌到0.015 USDT，则只值37.5 USDT。"],"mistakes":["以为承诺多少资金就能买到多少新币，没算超额认购后的分配比例。","认购前不看代币解锁时间表，上线后才发现大部分代币不能马上卖出。","把来路不明的“私募打新”当成交易所官方Launchpad参与。"],"faq":[{"q":"Launchpad打新一定赚钱吗？","a":"不一定。新币上线后价格可能低于认购价，加上平台币持仓的价格波动，整体结果可能是亏损。"},{"q":"参加Launchpad需要什么条件？","a":"通常需要完成KYC，并在快照期内持有一定数量的平台币或稳定币，具体要求和受限地区以每次活动公告为准。"}],"title":"什么是Launchpad？交易所打新认购规则详解","description":"Launchpad打新是什么？了解IEO认购流程、超额认购时分配比例怎么算、退款机制，以及代币解锁和上线后跌破认购价的风险。","related":[["launchpool","Launchpool（质押挖新币）","Launchpool是交易所推出的新币挖矿活动：你在活动期间把指定代币或稳定币锁定到资金池中，按你在池子里所占的份额每天领取即将上线的新代币。"],["token-listing","上币（Token listing）","上币是指交易所正式开放某个代币的充值和交易，为它开设现货或合约交易对，让用户可以在平台上买卖，通常会提前发布上币公告和开盘时间。"],["token-unlock","代币解锁（Token Unlock）","代币解锁是指原本锁仓、不能交易的代币按预定时间表释放进入流通，常见于团队、投资人和生态基金的份额。"],["airdrop","空投（Airdrop）","空投是项目方免费向符合条件的钱包地址或用户发放代币的方式，常用于奖励早期用户、分散持币和推广项目。"]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"sub-account":{"slug":"sub-account","cat":"exchange-features","en":"Sub-account","contentLocale":"zh-Hans","term":"子账户（Sub-account）","aka":["子帐户","Sub-account","子账号"],"short":"子账户是在同一个交易所主账户下开设的独立交易账户，资产和仓位彼此隔离，可以分别用于不同策略、API机器人或资金用途，并由主账户统一管理。","body":["主账户可以创建多个子账户，在它们之间免费划转资金。每个子账户有自己的余额、仓位和API密钥，一个子账户爆仓不会直接影响其他子账户的资金。通常只有主账户需要做KYC，子账户共享主账户的认证和费率等级。",["常见用法有：把",["长期持有","hodl"],"的现货放在主账户，把高风险的合约策略放在单独的子账户；为每个交易机器人分配一个子账户和独立的API密钥，出问题时损失可控；把跟单资金与自己手动交易的资金分开，方便核算收益。"],["子账户能隔离仓位风险，但不能隔离账户安全风险：主账户被盗，所有子账户都会受影响。主账户要开启",["双重验证","two-factor-authentication"],"和",["提币白名单","withdrawal-whitelist"],"，子账户的API密钥只开必要的权限，不开提币权限。"]],"example":["假设你的主账户有20,000 ",["USDT","usdt"],"，你创建一个子账户专门做高",["杠杆","leverage"],"合约，只划入2,000 USDT。某次行情中，子账户的20倍杠杆仓位被",["强平","liquidation"],"，2,000 USDT全部亏光，但主账户的18,000 USDT不受影响。如果你当初直接在主账户里用全仓模式开同样的仓位，强平前系统会持续动用账户里的其他资金作为保证金，亏损可能远超2,000 USDT。"],"mistakes":["以为子账户能防盗号，主账户却没开双重验证。","给机器人的子账户API开启提币权限，密钥泄露后资金被转走。","子账户分得太多，忘记里面还有仓位或资金，导致漏管理。"],"faq":[{"q":"子账户需要单独做KYC吗？","a":"大多数交易所的子账户共享主账户的实名认证，不需要单独认证，具体以平台规则为准。"},{"q":"子账户之间划转要手续费吗？","a":"通常同一交易所内主账户和子账户之间的划转是免费且即时到账的，不需要走链上提币。"}],"title":"什么是交易所子账户？用途与风险隔离","description":"交易所子账户是什么？了解子账户如何隔离合约仓位风险、怎样给交易机器人分配API，以及为什么主账户安全仍然最重要。","related":[["unified-trading-account","统一账户（Unified trading account）","统一账户是交易所把现货、杠杆、合约和期权等交易放在同一个账户中的模式，账户里多种资产可以按折算率共同作为保证金，盈亏可以相互抵消。"],["isolated-margin","逐仓保证金（Isolated Margin）","逐仓保证金是一种保证金模式，每个仓位只使用单独分配给它的保证金，仓位被强平时最多亏掉这部分，不会动用账户里的其他资金。"],["two-factor-authentication","双重验证（2FA）","双重验证（2FA）是在密码之外再加一道验证的登录与操作保护，常见形式有验证器 App 动态码、短信验证码和硬件安全密钥。"],["copy-trading","跟单交易（Copy trading）","跟单交易是交易所提供的一种功能，让你选择一位公开交易记录的带单员，按设定的比例或金额自动复制他的开仓和平仓操作。"]],"lesson":null,"coin":null,"tool":null,"cta":false},"vip-tier":{"slug":"vip-tier","cat":"exchange-features","en":"VIP fee tier","contentLocale":"zh-Hans","term":"VIP等级（VIP fee tier）","aka":["VIP费率等级","手续费等级","VIP等级"],"short":"VIP等级是交易所根据用户过去一段时间的交易量或资产余额划分的手续费档位，等级越高，挂单和吃单手续费率通常越低，还可能获得更高的提币额度等权益。","body":[["多数",["交易所","centralized-exchange"],"按近30天的现货或",["合约交易","futures-contract"],"量，以及账户资产或平台币持仓来评定VIP等级，满足其中一项或同时满足多项即可升级。每个等级对应一组挂单（Maker）和吃单（Taker）费率，高等级的",["挂单费","maker-taker-fees"],"率甚至可能为零或为负。"],["对普通用户来说，最低几个等级之间的差别往往不大；但对高频交易者、机器人策略和",["做市商","market-maker"],"来说，费率差距会直接决定策略能否盈利。部分交易所还会给高等级用户提供专属客服、更高的API频率限制和提币额度。"],["评定周期通常每天更新，",["交易量","trading-volume"],"下降后等级会回落。不同交易所的等级门槛、计算方式和费率表都不同，也会定期调整，需要以官方费率页面为准。"]],"example":["假设某交易所VIP0的合约吃单费率为0.10%，VIP1为0.09%，升到VIP1需要近30天合约交易量达到5,000,000 ",["USDT","usdt"],"。你每月刚好交易5,000,000 USDT，全部是吃单：在VIP0要付5,000 USDT手续费，在VIP1要付4,500 USDT，每月省下500 USDT。但如果你每月只交易50,000 USDT，两个等级的差额只有5 USDT，没必要为了冲等级而增加交易。"],"mistakes":["为了冲VIP等级刻意放大交易量，结果交易亏损远超省下的手续费。","只看VIP费率表，不知道挂单和吃单费率不同、对应的成交方式也不同。","以为等级达到后永久有效，忽略了每日按近30天数据重新评定。"],"faq":[{"q":"交易所VIP等级怎么升级？","a":"一般根据近30天交易量或账户资产、平台币持仓来评定，达到对应门槛后系统自动升级，具体标准见交易所的费率页面。"},{"q":"VIP等级会掉吗？","a":"会。等级通常每天按最近一段时间的数据重新计算，交易量或资产低于门槛后会降回相应等级。"}],"title":"什么是交易所VIP等级？手续费等级怎么算","description":"交易所VIP等级是什么？了解VIP手续费等级如何按交易量和资产评定、挂单吃单费率的差异，以及什么情况下值得追求更高等级。","related":[["maker-taker-fees","挂单费与吃单费（Maker/Taker Fee）","挂单费与吃单费是交易所按订单角色收取的两档手续费：挂在订单簿上等待成交、提供流动性的一方付挂单费，立即与已有挂单成交的一方付吃单费。"],["referral-code","邀请码（返佣）","邀请码是交易所发给用户或合作方的推荐编号，新用户注册时填写后，双方可能获得手续费返佣、注册奖励等，具体权益由交易所的推荐计划规定。"],["trading-volume","成交量（Trading Volume）","成交量是在一段时间内实际成交的资产数量或金额，例如 24 小时成交量，用来衡量一个币或一个市场的交易活跃程度。"],["market-maker","做市商（Market Maker）","做市商是在订单簿上持续同时挂出买单和卖单、为市场提供流动性的交易者或机构，主要通过买卖价差和交易所的挂单返佣获利。"]],"lesson":null,"coin":null,"tool":"/rates","cta":false},"token-listing":{"slug":"token-listing","cat":"exchange-features","en":"Token listing","contentLocale":"zh-Hans","term":"上币（Token listing）","aka":["上线","新币上线","上所","Listing"],"short":"上币是指交易所正式开放某个代币的充值和交易，为它开设现货或合约交易对，让用户可以在平台上买卖，通常会提前发布上币公告和开盘时间。","body":[[["交易所","centralized-exchange"],"上币前一般会评估项目的团队、代码、",["代币经济模型","tokenomics"],"、",["流动性","liquidity"],"和合规风险。上币公告通常写明开放充值的时间、开盘交易时间、",["交易对","trading-pair"],"和提币开放时间；部分新币会先进入带有风险提示的“观察区”或“创新区”。"],["大型交易所的上币消息常引发短期价格剧烈波动：公告后链上价格可能迅速上涨，开盘后又可能因早期持有者、",["空投","airdrop"],"用户集中卖出而快速回落。开盘初期盘口深度薄，",["市价单","market-order"],"的滑点可能很大。"],"要警惕打着“内幕上币消息”“保证上大所”旗号的骗局。真实的上币信息只以交易所官方公告为准，正规交易所也不会向用户收费“帮忙上币”。"],"example":"假设某新币在交易所开盘，开盘价0.10 USDT，15分钟内冲到0.30 USDT，随后回落到0.15 USDT。如果你在0.30 USDT用1,000 USDT市价追入，约买到3,333枚，回落到0.15 USDT时只值约500 USDT，亏损一半。若开盘时盘口很薄，你的市价单还可能因为滑点以平均0.33 USDT成交，只买到约3,030枚，回落后价值约455 USDT。","mistakes":["在开盘第一分钟用市价单追高，被滑点和随后的回落双重打击。","相信社群里的“内幕上币消息”，提前高价买入或付费“预约名额”。","不看上币公告中的充值和提币开放时间，导致资产转错时间或卡在路上。"],"faq":[{"q":"代币上了大交易所一定会涨吗？","a":"不一定。上币可能带来短期关注和流动性，但开盘后集中抛售很常见，价格既可能上涨也可能大幅回落。"},{"q":"怎么知道某个币要上哪个交易所？","a":"以交易所官方公告为准。社群或私信里流传的上币消息真假难辨，不应据此交易或付费。"}],"title":"什么是上币？交易所新币上线的规则与风险","description":"交易所上币是什么意思？了解上币公告包含哪些信息、新币开盘时价格为何剧烈波动、滑点如何影响成交，以及常见的上币骗局。","related":[["delisting","下架（Delisting）","下架是指交易所停止某个代币或交易对的交易服务，通常先发布公告、给出停止交易和停止提币的时间，之后用户只能在规定期限内把资产提走或兑换。"],["launchpool","Launchpool（质押挖新币）","Launchpool是交易所推出的新币挖矿活动：你在活动期间把指定代币或稳定币锁定到资金池中，按你在池子里所占的份额每天领取即将上线的新代币。"],["liquidity","流动性（Liquidity）","流动性是指一个资产能否在不明显推动价格的情况下快速买入或卖出，流动性越好，买卖价差越窄、大额成交的滑点越小。"],["altcoin","山寨币（Altcoin）","山寨币是指比特币以外的所有加密货币，包括以太坊、Solana 等公链币，也包括各种应用代币和 Meme 币。"]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"stock-perpetuals":{"slug":"stock-perpetuals","cat":"tokenized-assets","en":"Stock perpetuals","contentLocale":"zh-Hans","term":"股票永续合约（Stock perpetuals）","aka":["美股永续合约","股票合约","股票永续"],"short":"股票永续合约是跟踪某只股票或股票指数价格、没有到期日的衍生品合约，用USDT等稳定币作保证金，可以做多做空并使用杠杆，通过资金费率与标的价格保持一致。","body":[["它的机制和BTC",["永续合约","perpetual-futures"],"基本相同：你不持有任何股票，只是押注价格涨跌。合约价格以",["指数价格","index-price"],"为参考，",["资金费率","funding-rate"],"让合约价格贴近标的价格；你可以选择逐仓或全仓，设置止盈止损。部分",["中心化交易所","centralized-exchange"],"和",["链上永续合约","perp-dex"],"DEX都推出了此类产品。"],["与加密资产不同，股票只在证券交易所的开盘时间产生真实价格。休市、周末和节假日期间，合约的指数价格可能依赖盘前盘后数据或被暂时冻结，开盘时可能出现跳空，此时",["止损单","stop-loss"],"可能以远差于预设价格的价位成交。"],"因此股票永续合约同时叠加了杠杆风险和跳空风险，财报发布、重大消息公布时波动尤其剧烈。各平台对交易时间、最大杠杆、指数来源和休市处理的规定都不同，要先阅读合约规格说明。"],"example":"假设某股票价格为400美元，你用2,000 USDT保证金、5倍杠杆做多，名义仓位10,000 USDT，相当于25股的价格敞口。该公司盘后发布财报，次日开盘价跳空跌10%到360美元，你的仓位亏损1,000 USDT，等于保证金的一半。即使你把止损设在380美元，跳空开盘也会让止损以接近360美元的价格成交。另外，如果资金费率为每8小时0.01%，持有多单每天要支付约3 USDT。","mistakes":["在财报或重大消息发布前持有高杠杆仓位，以为止损一定能按预设价成交。","不了解休市期间的价格机制，误以为合约24小时都和真实股价同步。","把股票永续合约当成持有股票，期待领取分红或投票权。"],"faq":[{"q":"股票永续合约和代币化股票有什么区别？","a":"股票永续合约是带杠杆的衍生品，可以做空，有资金费率和强平；代币化股票是现货代币，对应托管的真实股票，不使用杠杆。"},{"q":"美股休市时股票永续合约还能交易吗？","a":"取决于平台规则。有的平台在休市时继续交易但价格参考有限，有的会限制交易，开盘时都可能出现跳空。"}],"title":"什么是股票永续合约？杠杆、资金费率与跳空风险","description":"股票永续合约是什么？了解美股永续合约如何用稳定币保证金做多做空、资金费率作用、休市期间的价格机制和开盘跳空风险。","related":[["tokenized-stocks","代币化股票（Tokenized stocks）","代币化股票是把上市公司股票的价格和经济权益映射到区块链代币上的产品，通常由发行方托管真实股票并按1:1发行代币，可在交易所或链上交易。"],["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。"],["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
